508:   /**
509:    * Single-statement bulk upsert using JSONB → UNNEST.
510:    *
511:    * Strategy
512:    *   1. Serialize rows to a JSONB array (one parameter, regardless of count).
513:    *   2. UNROLL them server-side with `jsonb_to_recordset`.
514:    *   3. INSERT … ON CONFLICT (translation, bookId, chapter, verse) DO UPDATE.
515:    *
516:    * One round-trip per call — N independent upserts collapse into one.
517:    * Idempotent thanks to the unique constraint already in the schema.
518:    *
519:    * NOTE: rows must all share the same shape. We chunk to 1000 to stay clear
520:    * of Postgres' 1 GB max parameter size for any pathological caller.
521:    */
522:   private async bulkUpsertVerses(
523:     rows: Array<{
524:       book: string;
525:       bookId: number;
526:       chapter: number;
527:       verse: number;
528:       text: string;
529:       translation: string;
530:       testament: string;
531:       copyright: string | null | undefined;
532:       textDirection: string;
533:     }>,
534:   ): Promise<number> {
535:     if (rows.length === 0) return 0;
536: 
537:     const CHUNK = 1000;
538:     let written = 0;
539:     for (let i = 0; i < rows.length; i += CHUNK) {
540:       const slice = rows.slice(i, i + CHUNK);
541:       const payload = JSON.stringify(slice);
542: 
543:       // Postgres uses gen_random_uuid() (pgcrypto in default extensions on
544:       // Supabase / pgcrypto-enabled installs). We rely on the column's lack
545:       // of default and supply UUIDs explicitly via gen_random_uuid().
546:       const result = await this.prisma.$executeRaw`
547:         INSERT INTO "BibleVerse"
548:           (id, book, "bookId", chapter, verse, text, translation, testament,
549:            copyright, "textDirection")
550:         SELECT
551:           gen_random_uuid()::text,
552:           v.book, v."bookId", v.chapter, v.verse, v.text, v.translation,
553:           v.testament, v.copyright, v."textDirection"
554:         FROM jsonb_to_recordset(${payload}::jsonb) AS v(
555:           book          text,
556:           "bookId"      integer,
557:           chapter       integer,
558:           verse         integer,
559:           text          text,
560:           translation   text,
561:           testament     text,
562:           copyright     text,
563:           "textDirection" text
564:         )
565:         ON CONFLICT (translation, "bookId", chapter, verse)
566:         DO UPDATE SET
567:           text            = EXCLUDED.text,
568:           copyright       = EXCLUDED.copyright,
569:           "textDirection" = EXCLUDED."textDirection";
570:       `;
571:       written += Number(result);
572:     }
573:     return written;
574:   }
