71:         if (this.redis && !this.redis['hasLoggedError']) {
72:           this.logger.warn(`Redis L2 cache unavailable: ${err.message}`);
73:           this.redis['hasLoggedError'] = true;
74:         }
75:       });
76:       this.redis.connect().catch((err) => {
77:         this.logger.warn(
78:           `Redis L2 cache init failed: ${(err as Error).message}`,
79:         );
80:         this.redis = null;
81:       });
82:     }
83:   }
84: 
85:   async onModuleDestroy(): Promise<void> {
86:     await this.redis?.quit().catch(() => {});
87:   }
88: 
89:   // ─── Cache helpers ──────────────────────────────────────────────────────
90: 
91:   private cacheKey(normalized: string): string {
92:     // SHA-256 keeps Redis keys bounded (8KB texts → 64-char hex) and avoids
93:     // weird chars in keys.
94:     return `emb:768:${createHash('sha256').update(normalized).digest('hex')}`;
95:   }
96: 
97:   private async readCache(normalized: string): Promise<number[] | null> {
98:     // L1
99:     const l1 = this.embeddingCache.get(normalized);
100:     if (l1 && Date.now() - l1.timestamp < this.L1_TTL_MS) {
101:       return l1.embedding;
102:     }
103:     // L2
104:     if (this.redis && this.redis.status === 'ready') {
105:       try {
106:         const raw = await this.redis.get(this.cacheKey(normalized));
107:         if (raw) {
108:           const parsed = JSON.parse(raw) as number[];
109:           // Promote to L1.
110:           this.setL1(normalized, parsed);
111:           return parsed;
112:         }
113:       } catch (err) {
114:         this.logger.warn(`L2 read failed: ${(err as Error).message}`);
115:       }
116:     }
117:     return null;
118:   }
119: 
120:   private async writeCache(
121:     normalized: string,
122:     embedding: number[],
123:   ): Promise<void> {
124:     this.setL1(normalized, embedding);
125:     if (this.redis && this.redis.status === 'ready') {
126:       // Fire-and-forget; latency mustn't block the caller.
127:       this.redis
128:         .setex(
129:           this.cacheKey(normalized),
130:           this.L2_TTL_S,
131:           JSON.stringify(embedding),
132:         )
133:         .catch((err) =>
134:           this.logger.warn(`L2 write failed: ${(err as Error).message}`),
135:         );
136:     }
137:   }
138: 
139:   private setL1(key: string, embedding: number[]): void {
140:     // Remove antes de inserir para que a chave vá ao final da ordem de inserção do Map
141:     this.embeddingCache.delete(key);
142:     this.embeddingCache.set(key, { embedding, timestamp: Date.now() });
143:     if (this.embeddingCache.size > this.MAX_CACHE_SIZE) {
144:       // Map.keys() retorna na ordem de inserção — a primeira chave é a mais antiga (LRU)
145:       const oldest = this.embeddingCache.keys().next().value;
146:       if (oldest) this.embeddingCache.delete(oldest);
147:     }
148:   }
149: 
150:   /**
151:    * Normaliza o texto antes de criar o embedding.
152:    * Reduz tokens desnecessários = menos custo.
153:    */
154:   private normalizeText(text: string): string {
155:     return text
156:       .toLowerCase()
157:       .replace(/\s+/g, ' ') // colapsa espaços
158:       .replace(/[^\w\sàáâãéêíóôõúç.,;:!?()"-]/gi, '') // remove chars especiais
159:       .trim()
160:       .slice(0, 8000); // Limite para evitar tokens excessivos (~2000 tokens)
161:   }
162: 
163:   /**
164:    * Gera um embedding determinístico de 768 dimensões baseado no texto.
165:    */
166:   private generateLocalFallbackEmbedding(text: string): number[] {
167:     const vector = new Array(this.VECTOR_DIM).fill(0);
168:     const words = text.split(/\s+/).filter((w) => w.length > 2);
169: 
170:     if (words.length === 0) {
171:       for (let i = 0; i < text.length; i++) {
172:         const idx = (text.charCodeAt(i) * 17) % this.VECTOR_DIM;
173:         vector[idx] += 0.1;
174:       }
175:     } else {
176:       words.forEach((word) => {
177:         let hash = 0;
178:         for (let i = 0; i < word.length; i++) {
179:           hash = (hash << 5) - hash + word.charCodeAt(i);
180:           hash |= 0;
181:         }
182:         const idx = Math.abs(hash) % this.VECTOR_DIM;
183:         vector[idx] += 1.0;
184:       });
185:     }
186: 
187:     const magnitude = Math.sqrt(
188:       vector.reduce((sum, val) => sum + val * val, 0),
189:     );
190:     return magnitude === 0 ? vector : vector.map((v) => v / magnitude);
191:   }
192: 
193:   /**
194:    * Cria embedding para um texto único via Google Gemini.
195:    */
196:   async createEmbedding(text: string): Promise<number[]> {
197:     const normalized = this.normalizeText(text);
198: 
199:     const cached = await this.readCache(normalized);
200:     if (cached) return cached;
201: 
202:     if (this.genAI) {
203:       try {
204:         // @google/genai 2.x: a chamada de embedding é única (sem
205:         // getGenerativeModel intermediário). `contents` aceita string
206:         // ou array. `config` carrega taskType + outputDimensionality.
207:         const result = await this.genAI.models.embedContent({
208:           model: 'gemini-embedding-001',
209:           contents: normalized,
210:           config: {
211:             taskType: 'RETRIEVAL_DOCUMENT',
212:             outputDimensionality: 768,
213:           },
214:         });
215:         const embedding = result.embeddings?.[0]?.values;
216:         if (!embedding) throw new Error('Gemini retornou embedding vazio');
217:         await this.writeCache(normalized, embedding);
218:         return embedding;
219:       } catch (error) {
220:         this.logger.error(`Erro Gemini embedding: ${(error as Error).message}`);
221:       }
222:     }
223: 
224:     if (this.openai) {
225:       try {
226:         const res = await this.openai.embeddings.create({
227:           model: 'text-embedding-3-small',
228:           input: normalized,
229:           dimensions: this.VECTOR_DIM,
230:         });
231:         const embedding = res.data[0].embedding;
232:         await this.writeCache(normalized, embedding);
233:         return embedding;
234:       } catch (error) {
235:         this.logger.error(`Erro OpenAI embedding: ${(error as Error).message}`);
236:       }
237:     }
238: 
239:     const fallback = this.generateLocalFallbackEmbedding(normalized);
240:     await this.writeCache(normalized, fallback);
241:     return fallback;
242:   }
243: 
244:   /**
245:    * Cria embeddings em batch via Gemini.
246:    */
247:   async createBatchEmbeddings(texts: string[]): Promise<number[][]> {
248:     if (!this.genAI) {
249:       return texts.map((t) =>
250:         this.generateLocalFallbackEmbedding(this.normalizeText(t)),
251:       );
252:     }
253: 
254:     const normalized = texts.map((t) => this.normalizeText(t));
255:     // Resolve all cache lookups in parallel (L1 sync, L2 async).
256:     const results: (number[] | null)[] = await Promise.all(
257:       normalized.map((n) => this.readCache(n)),
258:     );
259: 
260:     const uncachedIndices = results
261:       .map((r, i) => (r === null ? i : -1))
262:       .filter((i) => i >= 0);
263: 
264:     if (uncachedIndices.length === 0) return results as number[][];
265: 
266:     try {
267:       const uncachedTexts = uncachedIndices.map((i) => normalized[i]);
268: 
269:       // Process in small sub-batches to prevent undici socket exhaustion (ENOMEM / fetch failed)
270:       const subBatchSize = 10;
271:       for (let i = 0; i < uncachedIndices.length; i += subBatchSize) {
272:         const subBatch = uncachedIndices.slice(i, i + subBatchSize);
273:         await Promise.all(
274:           subBatch.map(async (originalIndex, j) => {
275:             const text = uncachedTexts[i + j];
276:             const result = await this.genAI!.models.embedContent({
277:               model: 'gemini-embedding-001',
278:               contents: text,
279:               config: {
280:                 taskType: 'RETRIEVAL_DOCUMENT',
281:                 outputDimensionality: 768,
282:               },
283:             });
284: 
285:             const embedding = result.embeddings?.[0]?.values;
286:             if (!embedding) throw new Error('Gemini retornou embedding vazio');
287:             results[originalIndex] = embedding;
288:             await this.writeCache(normalized[originalIndex], embedding);
289:           }),
290:         );
291:       }
292: 
293:       return results as number[][];
294:     } catch (error) {
295:       this.logger.error(`Erro Gemini embedding: ${(error as Error).message}`);
296:       return texts.map((t) =>
297:         this.generateLocalFallbackEmbedding(this.normalizeText(t)),
298:       );
299:     }
300:   }
301: 
302:   /**
303:    * Calcula a similaridade cosseno entre dois vetores.
304:    * Usado para busca semântica local sem precisar do pgvector.
305:    */
306:   cosineSimilarity(a: number[], b: number[]): number {
307:     if (a.length !== b.length) return 0;
308: 
309:     let dotProduct = 0;
310:     let normA = 0;
311:     let normB = 0;
312: 
313:     for (let i = 0; i < a.length; i++) {
314:       dotProduct += a[i] * b[i];
315:       normA += a[i] * a[i];
316:       normB += b[i] * b[i];
317:     }
318: 
319:     const denominator = Math.sqrt(normA) * Math.sqrt(normB);
320:     return denominator === 0 ? 0 : dotProduct / denominator;
321:   }
322: 
323:   /** Wipes both cache tiers — used by tests and admin tools. */
324:   async clearCache(): Promise<void> {
325:     this.embeddingCache.clear();
326:     if (this.redis && this.redis.status === 'ready') {
327:       // SCAN-DEL the namespace to avoid blocking-KEYS in production.
328:       const stream = this.redis.scanStream({ match: 'emb:768:*', count: 200 });
329:       const pipeline = this.redis.pipeline();
330:       let pending = 0;
331:       stream.on('data', (keys: string[]) => {
332:         for (const k of keys) {
333:           pipeline.del(k);
334:           pending++;
335:         }
336:       });
337:       await new Promise<void>((resolve, reject) => {
338:         stream.on('end', resolve);
339:         stream.on('error', reject);
340:       });
341:       if (pending > 0) await pipeline.exec();
342:     }
343:     this.logger.log('Cache de embeddings (L1 + L2) limpo.');
344:   }
345: 
346:   /** Retorna estatísticas do cache */
347:   getCacheStats(): { size: number; maxSize: number; ttlMinutes: number } {
348:     return {
349:       size: this.embeddingCache.size,
350:       maxSize: this.MAX_CACHE_SIZE,
351:       ttlMinutes: this.L1_TTL_MS / 60_000,
352:     };
353:   }
